        if not page then return end
        task.delay(0.06, function()
            if not page.Btn.Parent then return end
            local k = math.max(navScale.Scale, 0.01)
            local cx = (page.Btn.AbsolutePosition.X + page.Btn.AbsoluteSize.X / 2 - navBar.AbsolutePosition.X) / k
            navDot.Visible = false
            Tween(navDot, { Position = UDim2.new(0, cx, 1, 7) }, 0.25)
        end)
    end
