    local function selectPage(page)
        for _, p in ipairs(Window.Pages) do
            local on = p == page
            Tween(p.Btn, { BackgroundTransparency = on and 0.8 or 1 }, 0.2)
            Tween(p.Chip, { BackgroundTransparency = on and 0 or 1 }, 0.2)
            Tween(p.BtnStroke, { Transparency = on and 0.55 or 1 }, 0.2)
            Tween(p.NameLbl, { TextColor3 = on and Theme.Text or Theme.SubText }, 0.2)
            p.TabBar.Visible = on
            if not on then
                for _, t in ipairs(p.Tabs) do t.Frame.Visible = false end
            end
        end
        Window.CurrentPage = page
        page:_selectTab(page.CurrentTab or page.Tabs[1])
        moveDot(page)
    end

