    TargetCard:AddButton({ Name = "Craft Rainbow Fenrir (1-Click)", Primary = false, Style = "Success", Callback = Task("Rainbow Fenrir", function()
        local ok, msg = CraftRainbow(FindPetByName("fenrir", "Pet_Egg2_5"))
