-- Ported feature groups from the older Loot To Forge build.
do
    local RewardsPage = Window:AddPage({ Name = "Rewards" })
    local RewardsTab = RewardsPage:AddTab("Rewards")
    local RewardCard = RewardsTab:AddCard("Rewards", "Left")
    local FriendsCard = RewardsTab:AddCard("Friends", "Right")
    local SeasonCardLegacy = RewardsTab:AddCard("Season", "Right")
    local CodesCard = RewardsTab:AddCard("Codes", "Left")

    local rewardState, rewardLoops = {}, {}

    local function callRewardRemote(folder, name, ...)
        local ok, remote = pcall(Shared.Util.Remote, folder, name)
        if not ok or not remote then return false end
        local args = table.pack(...)
        if remote:IsA("RemoteFunction") then
            return pcall(remote.InvokeServer, remote, table.unpack(args, 1, args.n))
        end
        return pcall(remote.FireServer, remote, table.unpack(args, 1, args.n))
    end

    local function startRewardLoop(spec)
        if rewardLoops[spec.key] then return end
        rewardLoops[spec.key] = true
        task.spawn(function()
            while rewardState[spec.key] do
                pcall(spec.run)
                task.wait(spec.interval or 45)
            end
            rewardLoops[spec.key] = nil
        end)
    end

    local function addRewardToggle(spec)
        RewardCard:AddToggle({ Name = spec.name, Default = false, Callback = function(v)
            rewardState[spec.key] = v
            if v then startRewardLoop(spec) end
        end })
    end

    addRewardToggle({
        key = "online", name = "Claim Online Gifts",
        run = function()
            for giftId = 1, 12 do
                callRewardRemote("Online", "TryClaimRE", tostring(giftId))
                task.wait(0.05)
            end
        end,
    })
    addRewardToggle({
        key = "offline", name = "Claim Offline Reward",
        run = function() callRewardRemote("Offline", "TryClaimOfflineRewardRE") end,
    })
    addRewardToggle({
        key = "index", name = "Claim Index EXP And Levels",
        run = function()
            callRewardRemote("Index", "TryClaimIndexExpRF")
            callRewardRemote("Index", "TryClaimLevelRewardRF")
        end,
    })
    addRewardToggle({
        key = "season", name = "Claim Season Rewards",
        run = function()
            callRewardRemote("Season", "TryClaimAllRewardRE")
            callRewardRemote("Season", "TryClaimDailyTicRE")
        end,
    })
    addRewardToggle({
        key = "towerTicket", name = "Claim Daily Tower Ticket",
        run = function() callRewardRemote("Dungeon", "TryClaimDailyDunTicRE") end,
    })
    addRewardToggle({
        key = "quests", name = "Claim Event Quests",
        run = function() callRewardRemote("EnhantEvent", "TryClaimQuestRE") end,
    })
    addRewardToggle({
        key = "update", name = "Claim Update And Group Gifts",
        run = function()
            callRewardRemote("UpdateLog", "TryClaimUPDRewardRE")
            callRewardRemote("Player", "TryJoinGroupRE")
        end,
    })

    local rewardStatus = RewardCard:AddLabel("Enable any reward toggle to run it periodically.")

    local friendAuto = false
    local friendLoop = false
    FriendsCard:AddToggle({ Name = "Auto Friend", Default = false, Callback = function(v)
        friendAuto = v
        if friendLoop then return end
        friendLoop = true
        task.spawn(function()
            while friendAuto do
                for _, player in ipairs(Players:GetPlayers()) do
                    if player ~= LocalPlayer then
                        local ok, isFriend = pcall(function()
                            return LocalPlayer:IsFriendsWith(player.UserId)
                        end)
                        if ok and not isFriend then
                            pcall(function() LocalPlayer:RequestFriendship(player) end)
                            task.wait(10)
                            break
                        end
                    end
                end
                task.wait(10)
            end
            friendLoop = false
        end)
    end })

    FriendsCard:AddButton({ Name = "Join Friend's Server", Primary = false, Callback = function()
        local TeleportService = game:GetService("TeleportService")
        local ok, friends = pcall(function() return LocalPlayer:GetFriendsOnline(200) end)
        if not ok or type(friends) ~= "table" then
            return Shared.notify("Joining a friend is not supported by this executor", "Friends")
        end
        for _, friend in ipairs(friends) do
            local placeId, jobId = friend.PlaceId, friend.GameId
            if placeId and jobId and jobId ~= game.JobId and (placeId == game.PlaceId or friend.UniverseId == game.GameId) then
                Shared.notify("Joining " .. tostring(friend.UserName or friend.DisplayName or "friend"), "Friends")
                pcall(function() TeleportService:TeleportToPlaceInstance(placeId, jobId, LocalPlayer) end)
                return
            end
        end
        Shared.notify("No friend is online in another server of this game", "Friends")
    end })

    local seasonLuck = false
    local seasonLuckLoop = false
    SeasonCardLegacy:AddToggle({ Name = "Spin Season Luck", Default = false, Callback = function(v)
        seasonLuck = v
        if seasonLuckLoop then return end
        seasonLuckLoop = true
        task.spawn(function()
            while seasonLuck do
                callRewardRemote("Season", "LuckRE", 1)
                task.wait(5)
            end
            seasonLuckLoop = false
        end)
    end })

    local codeValue = ""
    local autoCodes = false
    local codeLoop = false
    local CodeListUrl = "https://raw.githubusercontent.com/vaensigma/Corvus/refs/heads/main/Codes"

    local function redeemKnownCode(code)
        code = tostring(code or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if code == "" or code:sub(1, 1) == "#" then return end
        local ok = callRewardRemote("Code", "TryUseCodeRF", code)
        Shared.notify(ok and ("Tried code: " .. code) or ("Could not use code: " .. code), "Codes")
    end

    CodesCard:AddToggle({ Name = "Redeem Known Codes", Default = false, Callback = function(v)
        autoCodes = v
        if codeLoop then return end
        codeLoop = true
        task.spawn(function()
            while autoCodes do
                local ok, body = pcall(function() return game:HttpGet(CodeListUrl .. "?t=" .. tostring(os.time())) end)
                if ok and type(body) == "string" then
                    for line in body:gmatch("[^\r\n]+") do
                        local code = line:gsub("#.*", ""):gsub("^%s+", ""):gsub("%s+$", "")
                        if code ~= "" then
                            redeemKnownCode(code)
                            task.wait(1)
                        end
                    end
                end
                task.wait(21600)
            end
            codeLoop = false
        end)
    end })

    CodesCard:AddInput({ Name = "Code", Placeholder = "Type a code from the game's socials", Default = "", Callback = function(v)
        codeValue = tostring(v or "")
    end })
    CodesCard:AddButton({ Name = "Redeem", Primary = false, Callback = function()
        redeemKnownCode(codeValue)
    end })
    CodesCard:AddLabel("Codes redeemed through this page are sent to the game's code remote.")
end

