local AntiAfk = { Enabled = true, Blocked = 0 }
local AfkCard = InterfaceTab:AddCard("Anti AFK", "Right")
local afkStatus
AfkCard:AddToggle({ Name = "Anti AFK", Default = true, Callback = function(v)
    AntiAfk.Enabled = v
    if afkStatus then afkStatus:Set(v and "Status: Protected" or "Status: Off") end
end })
AfkCard:AddLabel("Stay online all night. Roblox boots idle players after 20 minutes, so this quietly taps for you and keeps you in the game while you farm.")
afkStatus = AfkCard:AddLabel("Status: Protected")
local afkCount = AfkCard:AddLabel("Idle kicks blocked: 0")

do
    local VirtualUser = game:GetService("VirtualUser")
    local GuiService = game:GetService("GuiService")
    local TeleportService = game:GetService("TeleportService")
    local alive = true
    local pulses = 0
    local reconnecting = false
    local autoReconnect = true

    local function pulse()
        pcall(function()
            VirtualUser:CaptureController()
            VirtualUser:ClickButton2(Vector2.new(0, 0))
        end)
        pcall(function()
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health > 0 and hum.MoveDirection.Magnitude == 0 then
                hum:Move(Vector3.new(0, 0, 0), true)
            end
        end)
    end

    local afkPulses = AfkCard:AddLabel("Keep-alive pulses: 0")
    AfkCard:AddToggle({ Name = "Auto Reconnect", Default = true, Description = "Rejoin automatically if Roblox disconnects you", Callback = function(v)
        autoReconnect = v
    end })

    -- Stop the game's own idle handlers from reaching the kick, where the executor allows it.
    pcall(function()
        for _, conn in ipairs(getconnections(LocalPlayer.Idled)) do
            if conn.Disable then conn:Disable() end
        end
    end)

    local idled = LocalPlayer.Idled:Connect(function()
        if not AntiAfk.Enabled then return end
        pulse()
        AntiAfk.Blocked = AntiAfk.Blocked + 1
        afkCount:Set("Idle kicks blocked: " .. AntiAfk.Blocked)
    end)

    task.spawn(function()
        while alive do
            for _ = 1, 50 do
                if not alive then return end
                task.wait(1)
            end
            if AntiAfk.Enabled then
                pulse()
                pulses += 1
                afkPulses:Set("Keep-alive pulses: " .. pulses)
            end
        end
    end)

    local errored = GuiService.ErrorMessageChanged:Connect(function()
        if not (AntiAfk.Enabled and autoReconnect) or reconnecting then return end
        reconnecting = true
        task.spawn(function()
            task.wait(3)
            local queue = queue_on_teleport or queueonteleport
            if queue and SeasonReload then pcall(queue, SeasonReload) end
            for _ = 1, 5 do
                if not alive then break end
                pcall(TeleportService.Teleport, TeleportService, game.PlaceId, LocalPlayer)
                task.wait(8)
            end
            reconnecting = false
        end)
    end)

    Window.reg({ Disconnect = function()
        alive = false
        idled:Disconnect()
        errored:Disconnect()
    end })
end

