    if read and type(text) == "string" and #text > 1000 then body = text end
end
if not body then
    local url = "https://raw.githubusercontent.com/LazyJiroHub/LazyHub/refs/heads/main/Folder/LootToForge.lua"
    local ok, text = pcall(game.HttpGet, game, url)
    if ok and type(text) == "string" then
        body = text
    else
        local requester = request or http_request or (syn and syn.request) or (http and http.request)
        if requester then
            local sent, reply = pcall(requester, { Url = url, Method = "GET" })
            body = sent and type(reply) == "table" and reply.Body or nil
        end
    end
end
if type(body) == "string" then
    local fn, err = loadstring(body)
    if fn then fn() else warn("[LazyJiro] reload failed: " .. tostring(err)) end
end]==]

    local connection

    function AutoExec.Source()
        return TEMPLATE:format(game.GameId)
    end

    function AutoExec.Set(enabled)
        if connection then
            connection:Disconnect()
            connection = nil
        end
        if not enabled then return end
        local queue = queue_on_teleport or queueonteleport
        if not queue then return end
        connection = LocalPlayer.OnTeleport:Connect(function(state)
            if state == Enum.TeleportState.Started then
                pcall(queue, AutoExec.Source())
            end
        end)
    end

    Window.reg({ Disconnect = function() AutoExec.Set(false) end })
end

